PRAGMA foreign_keys = ON;
DROP TABLE IF EXISTS quality_flags;
DROP TABLE IF EXISTS decisions;
DROP TABLE IF EXISTS company_founders;
DROP TABLE IF EXISTS founders;
DROP TABLE IF EXISTS companies;
DROP TABLE IF EXISTS sessions;
CREATE TABLE sessions (session_id TEXT PRIMARY KEY, session_label TEXT, period_json TEXT, official_labels INTEGER, official_prelabels INTEGER, official_total_accepted INTEGER, official_withdrawals INTEGER, official_note TEXT);
CREATE TABLE companies (company_id TEXT PRIMARY KEY, name TEXT NOT NULL, sector TEXT, project TEXT, UNIQUE(name));
CREATE TABLE founders (founder_id TEXT PRIMARY KEY, name TEXT NOT NULL, UNIQUE(name));
CREATE TABLE company_founders (company_id TEXT NOT NULL, founder_id TEXT NOT NULL, session_id TEXT NOT NULL, founder_raw TEXT, quality TEXT, PRIMARY KEY(company_id, founder_id, session_id), FOREIGN KEY(company_id) REFERENCES companies(company_id), FOREIGN KEY(founder_id) REFERENCES founders(founder_id), FOREIGN KEY(session_id) REFERENCES sessions(session_id));
CREATE TABLE decisions (decision_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, company_id TEXT NOT NULL, source_file TEXT, section TEXT, project TEXT, founders_raw TEXT, decision_raw TEXT, resultat_normalise TEXT, type_decision TEXT, status_requested TEXT, sector TEXT, tour TEXT, after_pitching TEXT, award_or_withdrawal TEXT, comments TEXT, quality_control TEXT, FOREIGN KEY(session_id) REFERENCES sessions(session_id), FOREIGN KEY(company_id) REFERENCES companies(company_id));
CREATE TABLE quality_flags (flag_id INTEGER PRIMARY KEY AUTOINCREMENT, record_id INTEGER, session_id TEXT, company TEXT, issue TEXT, detail TEXT);
